css:
*{
  font-family: sans-serif;
  font-size: 15px;
  box-sizing: border-box;
  text-align: justify;
  padding: 0;
  margin: 0;
}
.print-format{
    margin: 0;
    padding: 0;
    width: 800px;
    max-height: 300px;
}
h4{
  text-align: center;
  background: #17f;
  color: white;
  padding: 0.3cm;
  margin-top: 0.1cm;
}
article{
  padding: 1cm 3cm;
  page-break-inside: avoid;
  page-break-after: always;
}

h5{
  position: relative;
  font-weight: 600;
  margin: 0.8cm 0;
  font-size: 0.4cm;
}
h5::before{
  content: "5.";
  position: absolute;
  left: -1cm
}

p{
   text-align: justify;
}

img{
  width: 4cm;
  display: block;
  margin-left: auto;
}

@page {
  size: A4 portrait; /* Set page size to A4 and orientation to portrait */
  margin: 2cm; /* Apply a 2cm margin on all sides */
}
